bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {menuPage} from './src/telegram/menuPanel.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
const out=createCreatorTelegramFetch(fetch);
const api=createTelegramBotApi({token:readFileSync('/run/secrets/videobot_telegram_token','utf8').trim(),fetchImpl:out.fetch,timeoutMs:20000,baseUrl:process.env.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org'});
const client=await pool.connect();
try{
 await client.query('BEGIN');
 const q=await client.query("SELECT s.owner_user_id,s.revision,s.state FROM videobot_creator_sessions s JOIN videobot_listings l ON l.seller_user_id=s.owner_user_id WHERE l.listing_id=$1 FOR UPDATE OF s",['v26nov24invoice']);
 if(q.rows.length!==1)throw Error('OWNER_SESSION_NOT_UNIQUE');
 const row=q.rows[0],owner=Number(row.owner_user_id),rev=Number(row.revision);
 if(!Number.isSafeInteger(owner)||owner<=0||!Number.isSafeInteger(rev))throw Error('OWNER_SESSION_INVALID');
 const panel=menuPage('home');
 const sent=await api('sendMessage',{chat_id:owner,text:panel.text,reply_markup:panel.reply_markup,disable_notification:true});
 if(sent?.chat?.id!==owner||sent?.chat?.type!=='private'||!Number.isSafeInteger(sent.message_id)||sent.text!==panel.text||JSON.stringify(sent.reply_markup?.inline_keyboard.map(r=>r.map(x=>x.text)))!==JSON.stringify(panel.reply_markup.inline_keyboard.map(r=>r.map(x=>x.text))))throw Error('MENU_SEND_ACK_UNVERIFIED');
 const state={...row.state,screen:'home',waiting:null};
 const result=await client.query("UPDATE videobot_creator_sessions SET revision=$2,screen_message_id=$3,state=$4::jsonb,updated_at=NOW() WHERE owner_user_id=$1 AND revision=$5 RETURNING revision,screen_message_id,state->>'publishing' AS publishing",[owner,rev+1,sent.message_id,JSON.stringify(state),rev]);
 if(result.rowCount!==1||Number(result.rows[0].screen_message_id)!==sent.message_id||result.rows[0].publishing!==(row.state.publishing??null))throw Error('MENU_SESSION_READBACK_FAILED');
 await client.query('COMMIT');
 console.log('OWNER_MENU_TELEGRAM_SEND_AND_SESSION_READBACK=PASS');
}catch(e){await client.query('ROLLBACK').catch(()=>{});console.log('MENU_RECOVERY_ERROR',String(e.message).replace(/[0-9]{6,}:[A-Za-z0-9_-]{20,}/g,'[REDACTED]').slice(0,200));process.exitCode=70;}
finally{client.release();await pool.end();await out.close();}
JS
